; The ship pack hulls of the 128K build (Fessor's hulls, used with his permission): vertices-only blueprints generated by tools/ship128.py into work/elite128/ (never committed), filled like
; every other hull (types 20-28, records in fill128_packs.bin, bank 6 &6800). The chain below tells hullFindType (through mxHullType, commonxx.asm) which type a blueprint address is:
; A = type, carry clear on a match, else carry set. The order and numbers match PACK_HULLS in tools/ship128.py.
    INCLUDE "../../work/elite128/hull_packs.asm"
mxHullTypeImpl:                       ; DE = blueprint address
    IFDEF HULL_GECKO
    ld hl,shipdatGecko
    or a
    sbc hl,de
    ld a,20
    ret z
    ENDIF
    IFDEF HULL_COBRAMK1
    ld hl,shipdatCobraMk1
    or a
    sbc hl,de
    ld a,21
    ret z
    ENDIF
    IFDEF HULL_WORM
    ld hl,shipdatWorm
    or a
    sbc hl,de
    ld a,22
    ret z
    ENDIF
    IFDEF HULL_MORAY
    ld hl,shipdatMoray
    or a
    sbc hl,de
    ld a,23
    ret z
    ENDIF
    IFDEF HULL_MAMBA
    ld hl,shipdatMamba
    or a
    sbc hl,de
    ld a,24
    ret z
    ENDIF
    IFDEF HULL_ADDER
    ld hl,shipdatAdder
    or a
    sbc hl,de
    ld a,25
    ret z
    ENDIF
    IFDEF HULL_BOA
    ld hl,shipdatBoa
    or a
    sbc hl,de
    ld a,26
    ret z
    ENDIF
    IFDEF HULL_ANACONDA
    ld hl,shipdatAnaconda
    or a
    sbc hl,de
    ld a,27
    ret z
    ENDIF
    IFDEF HULL_SHUTTLE
    ld hl,shipdatShuttle
    or a
    sbc hl,de
    ld a,28
    ret z
    ENDIF
    scf
    ret
